Q: Why does std::println(std::vector) fail to compile? A: <p>In C++23, libc++ do not support both <a href="https://www.cppstories.com/2024/cpp23_lib/" rel="nofollow noreferrer">P2093 </a>(std::println) &amp; <a href="https://www.cppstories.com/2020/02/extra-format-cpp20.html/" rel="nofollow noreferrer">P2286 </a>(Formatting Ranges) but standard compliance only requires <code>&lt;format&gt;</code> to expose range <a href="https://wg21.link/P2286R8" rel="nofollow noreferrer">formatting</a>.</p>
<p>Code:</p>
<p>Simply add header file <code>#include &lt;format&gt;</code> with <code>&lt;print&gt;</code> &amp; <code>&lt;vector&gt;</code></p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;print&gt;
#include &lt;vector&gt;
#include &lt;format&gt; 

int main() {
    std::vector&lt;int&gt; v{1, 2, 3};
    std::println(&quot;{}&quot;, v); 
}
</code></pre>
<p>Output:</p>
<pre><code>ASM generation compiler returned: 0
Execution build compiler returned: 0
Program returned: 0
[1, 2, 3]
</code></pre>
<p><a href="https://godbolt.org/z/68TW3s6x8" rel="nofollow noreferrer">https://godbolt.org/z/68TW3s6x8</a></p>

Q: Extra non-character or empty character or absence is getting printed at the end of target string being matched by regex pattern using find() in java A: <pre><code>import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        String regex = &quot;((\\d\\d\\d\\d)(\\w\\w\\w)(\\W\\W))&quot;;
        String targetString = &quot;$()1287jga$%dp5000tag%!5000tag%!5000tag%!q1&quot;;
        Pattern pattern = Pattern.compile(regex);
        Matcher match = pattern.matcher(targetString); 
        while(match.find()) {
            String m = match.group();
            System.out.println(m);
            System.out.println(&quot;Pattern=&gt;&quot;
              + m
              + &quot;&lt;=at starting index &quot;
              + match.start() + &quot; ending index &quot;+ match.end());
        }
    }
}
</code></pre>
<p>Looks like that extra index 43 was coming from the last symbol in String variable called 'regex'. that symbol was &quot;*&quot; Which I removed and now final output becomes:<br />
<code>Pattern=&gt;5000tag%!&lt;=at starting index 32 ending index 41</code><br />
Hope that is what you were aiming for.</p>
<p>Also, you did:<br />
<code>String m = match.group();</code> and you also used <strong>match.group();</strong> in the first line of 'println' method. so using that 'm' instead makes output cleaner.</p>

Q: Delphi 13 macOS app and Drag &amp; Drop launch A: <p>You would have to edit the info.plist.TemplateOSX.xml file and add the proper keys for the document type. Here's an example that would associate &quot;.col&quot; files with your app. This is what I use, part of it was originally generated by AI.</p>
<pre><code>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;
&lt;!DOCTYPE plist PUBLIC &quot;-//Apple//DTD PLIST 1.0//EN&quot; &quot;http://www.apple.com/DTDs/PropertyList-1.0.dtd&quot;&gt;
&lt;plist version=&quot;1.0&quot;&gt;
    &lt;dict&gt;
        &lt;%VersionInfoPListKeys%&gt;
    &lt;%ExtraInfoPListKeys%&gt;


 &lt;!-- Declare the .col file type --&gt;
    &lt;key&gt;CFBundleDocumentTypes&lt;/key&gt;
    &lt;array&gt;
        &lt;dict&gt;
            &lt;key&gt;CFBundleTypeName&lt;/key&gt;
            &lt;string&gt;COL File&lt;/string&gt;

            &lt;key&gt;CFBundleTypeRole&lt;/key&gt;
            &lt;string&gt;Editor&lt;/string&gt;

            &lt;key&gt;LSHandlerRank&lt;/key&gt;
            &lt;string&gt;Owner&lt;/string&gt;

            &lt;key&gt;LSItemContentTypes&lt;/key&gt;
            &lt;array&gt;
                &lt;string&gt;com.yourcompany.col&lt;/string&gt;
            &lt;/array&gt;
        &lt;/dict&gt;
    &lt;/array&gt;

    &lt;!-- Define the custom UTI --&gt;
    &lt;key&gt;UTExportedTypeDeclarations&lt;/key&gt;
    &lt;array&gt;
        &lt;dict&gt;
            &lt;key&gt;UTTypeIdentifier&lt;/key&gt;
            &lt;string&gt;com.yourcompany.col&lt;/string&gt;

            &lt;key&gt;UTTypeDescription&lt;/key&gt;
            &lt;string&gt;COL File&lt;/string&gt;

            &lt;key&gt;UTTypeConformsTo&lt;/key&gt;
            &lt;array&gt;
                &lt;string&gt;public.data&lt;/string&gt;
            &lt;/array&gt;

            &lt;key&gt;UTTypeTagSpecification&lt;/key&gt;
            &lt;dict&gt;
                &lt;key&gt;public.filename-extension&lt;/key&gt;
                &lt;array&gt;
                    &lt;string&gt;col&lt;/string&gt;
                    &lt;string&gt;tcol&lt;/string&gt;
                &lt;/array&gt;
            &lt;/dict&gt;
        &lt;/dict&gt;
    &lt;/array&gt;
    &lt;/dict&gt;
&lt;/plist&gt;
</code></pre>
<p>Then in your Delphi application you need to respond to <code>NSApplication.openFile</code>. This is a bit tricky. Here's an example that adds it to the <code>TApplication</code> class using a class helper.</p>
<pre class="lang-pascal prettyprint-override"><code>unit FileAssoc;

interface

uses
  FMX.Forms;

type
  TApplicationFileOpenEvent = function(FileName: string): Boolean of object;

  ApplicationHelper = class helper for TApplication
  private
    class var FOnFileOpen: TApplicationFileOpenEvent;
    procedure InitializeApplicationHelper;
    class procedure SetOnFileOpen(const Value: TApplicationFileOpenEvent); static;
  public
    class property OnFileOpen: TApplicationFileOpenEvent read FOnFileOpen write SetOnFileOpen;
  end;


implementation

uses
  Consts, System.Math, Variants, TypInfo, Macapi.CocoaTypes, Macapi.Foundation,  Macapi.ObjectiveC, FMX.Platform.Mac,
  Macapi.ObjCRuntime, Macapi.CoreFoundation, MacApi.AppKit;

function CFToDelphiString(const CFStr: CFStringRef): string;
var
  Range: CFRange;
begin
  Range := CFRangeMake(0, CFStringGetLength(CFStr));
  SetLength(Result, Range.length);
  if Range.length = 0 then
    Exit;
  CFStringGetCharacters(CFStr, Range, @Result[1]);
end;

function ApplicationFileOpen(self: Pointer; _cmd: SEL; _application: Pointer; filename: CFStringRef): Boolean; cdecl;
var
  FName: string;
begin
  try
    FName := CFToDelphiString(filename);

    if Assigned(Application.OnFileOpen) then
      Result := Application.OnFileOpen(FName)
    else
      Result := False;
  except
    FMX.Forms.Application.HandleException(ExceptObject);
    Result := False;
  end;
end;

procedure ApplicationHelper.InitializeApplicationHelper;
var
  FAppDelegate: Pointer;
  FAppDelegateClass: Pointer;
  Delegate: NSApplicationDelegate;
begin
  // Add application.openfile to the Application Delegate
  Delegate := TNSApplication.Wrap(TNSApplication.OCClass.SharedApplication).delegate;
  FAppDelegate := (Delegate as ILocalObject).GetObjectID;

  FAppDelegateClass := object_getClass(FAppDelegate);
  class_addMethod(FAppDelegateClass, sel_getUid('application:openFile:'), @ApplicationFileOpen, 'B@:@@');
end;

class procedure ApplicationHelper.SetOnFileOpen(
  const Value: TApplicationFileOpenEvent);
begin
  FOnFileOpen := Value;
end;


initialization
  Application.InitializeApplicationHelper;
end.
</code></pre>
<p>And finally, if macOS doesn't see that your .plist file was updated, run this command and logout or restart your mac.</p>
<pre><code>/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -r -domain local -domain system -domain user
</code></pre>
